void Jumping::onComputeForce(float dt)
{
    Flying::onComputeForce(dt);
    if (flag11)
        return;
    Body* body = getHumanoid()->getRootBody();
    if (!body) {
        flag11 = true;
        return;
    }
    float jumpForce = (50.0f - body->getVelocity().linear.y) * 5000.0f;
    if (jumpForce <= 0.0f) {
        flag11 = true;
        return;
    }
    if (getFloorPrimitive()) {
